CREATE TABLE IF NOT EXISTS economic_intelligence_recalibration (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, feedback_count integer NOT NULL DEFAULT 0, average_feedback numeric(5,2) NOT NULL DEFAULT 0, network_weight numeric(5,2) NOT NULL DEFAULT 40, assessment_weight numeric(5,2) NOT NULL DEFAULT 35, evidence_weight numeric(5,2) NOT NULL DEFAULT 25, calibration_state text NOT NULL DEFAULT 'baseline', adjustment_notes jsonb NOT NULL DEFAULT '[]'::jsonb, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_recalibration_profile ON economic_intelligence_recalibration(profile_id,created_at DESC);